        techBase: "clan",
        introducedInEdition: "battletech-compendium", editionStats: { "battletech-compendium": { book: "BTC", page: 115, name: "ECM Suite", weight: 1, criticals: 1, notes: "Range 6 hexes, printed under Long. The text describes the Guardian ECM Suite only (BTC p.120), and the price list has only the Guardian, at 200,000 C-bills (BTC p.129)." }, "compendium-rules-of-warfare": { book: "BTC:RoW", page: 104, name: "ECM Suite", weight: 1, criticals: 1, cbills: 200000, notes: "Range 6 hexes, printed under Long. The Equipment section describes the Guardian ECM Suite, which nullifies enemy Beagle active probes, Artemis IV, Narc beacons and C3 links within 6 hexes (BTC:RoW p.116); the price list has only that suite, at 200,000 C-bills (BTC:RoW p.124). The list prices each weapon and item once for both technology bases (the ER Large Laser, ER PPC, Gauss Rifle, LB 10-X AC, Ultra AC/5, Streak SRM 2, Narc Missile Beacon, Anti-Missile System and TAG cost the same on either table), so the Inner Sphere price is entered (user ruling, 2026-10-08); BMR p.138 later prints the same figure for the Clan item." }, "master-rules": { book: "BMR", page: 117, name: "ECM Suite", weight: 1, criticals: 1, cbills: 200000, notes: "Effect radius 6 hexes, with the capabilities of the Guardian ECM suite in a lighter and smaller package: inside it, and along any line of sight traced through it, enemy active probes, Artemis IV, Narc bonuses and C3 links do not work. One to a unit (BMR p.126)." }, "master-rules-revised": { book: "BMR(R)", page: 123, name: "ECM Suite", weight: 1, criticals: 1, cbills: 200000, notes: "Effect radius 6 hexes, with the capabilities of the Guardian ECM suite in a lighter and smaller package: inside it, and along any line of sight traced through it, enemy active probes, Artemis IV, Narc bonuses and C3 links do not work. One to a unit (BMR(R) p.136)." } },
